using MediatR; using JTradeERP.Application.Common.Persistence;
namespace JTradeERP.Application.Features.Security.Administration.GetPermissions;
public sealed record GetPermissionsQuery(string? Search=null):IRequest<GetPermissionsResponse>; public sealed record PermissionItemResponse(Guid Id,string Code); public sealed record GetPermissionsResponse(IReadOnlyCollection<PermissionItemResponse> Items);
public sealed class GetPermissionsHandler(IApplicationDbContext db):IRequestHandler<GetPermissionsQuery,GetPermissionsResponse>{public Task<GetPermissionsResponse> Handle(GetPermissionsQuery r,CancellationToken ct){var q=db.Permissions.AsEnumerable();if(!string.IsNullOrWhiteSpace(r.Search))q=q.Where(x=>x.Code.Contains(r.Search,StringComparison.OrdinalIgnoreCase));return Task.FromResult(new GetPermissionsResponse(q.OrderBy(x=>x.Code).Select(x=>new PermissionItemResponse(x.Id,x.Code)).ToArray()));}}
public static class GetPermissionsEndpoint{public static void Map(IEndpointRouteBuilder e)=>e.MapGet("/permissions",async(string? search,ISender s,CancellationToken t)=>Results.Ok(await s.Send(new GetPermissionsQuery(search),t))).RequirePermission("Admin.Roles.Manage",Capability.Full);}
